export const translationCatalog: Readonly<Record<string, readonly string[]>> = translations
const position = { pt: 0, es: 1, zh: 2, fr: 3, hi: 4 } as const
export function t(text: string, locale: Language = language): string {
  return locale === "en" ? text : translations[text]?.[position[locale]] ?? text
}
export function tf(text: string, values: Record<string, string | number>, locale: Language = language): string {
  return t(text, locale).replace(/\{(\w+)\}/g, (match, key: string) => Object.hasOwn(values, key) ? String(values[key]) : match)
}
// Translate protocol values for display only; never alter identifiers sent upstream.
export function stateLabel(value: string, locale: Language = language): string {
  const labels: Record<string, string> = { pending: "Pending", running: "Running", completed: "Completed", error: "Failed", failed: "Failed", connected: "Connected", disconnected: "Disconnected", disabled: "Disabled", needs_auth: "Authentication required", needs_client_registration: "Registration required", available: "Available", unsupported: "Unsupported", enabled: "Enabled", idle: "Idle", working: "Working", busy: "Working", retry: "Retrying", todo: "Pending", in_progress: "Running", cancelled: "Cancelled", added: "Created", modified: "Modified", deleted: "Deleted", renamed: "Renamed", low: "Low", medium: "Medium", high: "High", max: "Max", none: "None", xhigh: "Xhigh", primary: "Primary", subagent: "Subagent", all: "All", documents: "Documents", images: "Images", code: "Code", remote: "Remote", local: "Local", config: "Configuration", discovered: "Discovered", unknown: "Unknown", denied: "Denied", approve: "Approved", deny: "Denied", executed: "Executed", accepted: "Accepted" }
  return labels[value] ? t(labels[value]!, locale) : value
}
export function initializeLocale(): void {
  document.documentElement.lang = language === "pt" ? "pt-BR" : language === "zh" ? "zh-CN" : language
}
